  "response": "<solution>\nimport numpy as np\nimport pandas as pd\n\n# Constants\nCOLUMNS = ['Column1', 'Column2', 'Column3', 'Column4', 'Column5']\n\ndef task_func(length, min_value=0, max_value=100):\n    \"\"\"\n    Randomly generate a pandas DataFrame with values in the specified range\n    and calculate the empirical cumulative distribution function (CDF) for each column.\n\n    Parameters:\n        length (int): Number of rows to generate.\n        min_value (int): Inclusive lower bound for generated values.\n        max_value (int): Exclusive upper bound for generated values.\n\n    Returns:\n        pd.DataFrame: A pandas DataFrame containing the calculated cumulative \n        distribution function (CDF) for each column.\n    \"\"\"\n    if length <= 0:\n        return pd.DataFrame(columns=COLUMNS)\n\n    # Generate random integer data within the specified range\n    data = np.random.randint(min_value, max_value, size=(length, len(COLUMNS)))\n    df = pd.DataFrame(data, columns=COLUMNS)\n\n    # Calculate the cumulative distribution function (CDF) for each column\n    cdf = df.apply(lambda x: x.value_counts(normalize=True).sort_index().cumsum())\n\n    # Forward fill to propagate the CDF values across the union of indices, \n    # and fill any leading NaNs with 0 to complete the CDF step function.\n    cdf = cdf.ffill().fillna(0)\n\n    return cdf\n</solution>",
